names = ["Аня", "Борис", "Вера"]
for i, name in enumerate(names, start=1):
    print(i, name)

nums = [1, 2, 3, 4, 5, 6]
result = []
for x in nums:
    if x % 2 == 0:
        result.append(x * x)
print(result)    # [4, 16, 36]

nums = [1, -2, -3, 4]
for x in nums:
    if x < 0:
        nums.remove(x)
print(nums)    # [1, -3, 4] — минус три уцелел!

result = []
for x in nums:
    if x >= 0:
        result.append(x)    # честный способ
